    }
  }
  \addlyrics {
    \markup {
      \center-column { double sharp }
    }
    sharp
    natural
    flat
    \markup {
      \center-column { double flat }
    }
  }
  \layout {
    \context {
      \Score
      \override SpacingSpanner.base-shortest-duration =
        #(ly:make-moment 1/32)
